import numpy as np, itertools
lines=open('init.xyz').read().split('\n')
n=int(lines[0]); S=[];X=[]
for l in lines[2:2+n]:
    p=l.split(); S.append(p[0]); X.append(np.array([float(v) for v in p[1:4]]))
bonds=set()
def B(i,j): bonds.add((min(i,j),max(i,j)))
for g in range(1,5): B(0,g)
for k in range(3):
    b=1+26*k; g=b; ring=list(range(b+1,b+6))
    for r in ring: B(g,r)
    for a in range(5): B(ring[a],ring[(a+1)%5])
    for j in range(5):
        m=b+6+4*j; B(ring[j],m)
        for t in range(3): B(m,m+1+t)
B(79,80);B(80,81);B(81,82);B(82,83);B(83,84);B(84,79)
B(81,85)
for t in range(3): B(85,86+t)
B(84,89);B(82,90);B(82,91);B(83,92)
CR=list(range(92,97))
for a in range(5): B(CR[a],CR[(a+1)%5])
B(92,97)
for t in range(3): B(97,98+t)
for k in range(1,5):
    m=97+4*k; B(CR[k],m)
    for t in range(3): B(m,m+1+t)
bad=[]
for i,j in itertools.combinations(range(n),2):
    if (i,j) in bonds: continue
    d=np.linalg.norm(X[i]-X[j])
    if d<1.5: bad.append((i,j,S[i],S[j],round(d,2)))
print('clashes:',bad)
# min nonbonded overall
mn=(9e9,None)
for i,j in itertools.combinations(range(n),2):
    if (i,j) in bonds: continue
    d=np.linalg.norm(X[i]-X[j])
    if d<mn[0]: mn=(d,(i,j,S[i],S[j]))
print('min nonbonded', round(mn[0],2), mn[1])
# Ga-ring centroid distances
for k in range(3):
    b=1+26*k; ring=list(range(b+1,b+6))
    c=np.mean([X[r] for r in ring],axis=0)
    print('Ga',b,'cent',round(np.linalg.norm(X[b]-c),2))
# chelate ring planarity
sel=[79,80,81,82,83,84]
P=np.array([X[i] for i in sel]); c=P.mean(axis=0)
u,s,vt=np.linalg.svd(P-c); print('chelate planar rms out-of-plane', round(s[2]/np.sqrt(6),3))
